// Test unordered disjoint open-neighborhood unions B(uv)=N(u) U N(v) for red edges; triangle-free implies |B|=d(u)+d(v) and includes both endpoints. Disjoint balls give exactly the two-red-diagonal recolorable squares. Input graph6 single-byte n.
use std::io::{self,BufRead};
fn blue(a:&[u64],mut p:u64,k:u32)->bool{if k==0{return true}while p.count_ones()>=k{let j=p.trailing_zeros() as usize;p&=p-1;if blue(a,p&!a[j],k-1){return true}}false}
fn main(){let k:u32=std::env::args().nth(1).unwrap().parse().unwrap();for line in io::stdin().lock().lines(){let s=line.unwrap();let b=s.as_bytes();let n=(b[0]-63)as usize;assert!(n<63);let f=(1u64<<n)-1;let mut a=vec![0u64;n];let mut es=vec![];let mut h=0;for j in 0..n{for i in 0..j{if (b[1+h/6]-63)>>(5-h%6)&1!=0{a[i]|=1<<j;a[j]|=1<<i;es.push((i,j))}h+=1}}let balls:Vec<_>=es.iter().map(|&(i,j)|{assert!(a[i]&a[j]==0);a[i]|a[j]}).collect();let mut add=0;for i in 0..n{for j in 0..i{if a[i]>>j&1==0 && a[i]&a[j]==0{add+=1}}}let(mut pairs,mut short,mut pass)=(0,0,0);for j in 0..balls.len(){for i in 0..j{if balls[i]&balls[j]!=0{continue}pairs+=1;let u=f&!(balls[i]|balls[j]);if u.count_ones()<k-3{short+=1;pass+=1}else if !blue(&a,u,k-3){pass+=1}}}let mut ds:Vec<_>=a.iter().map(|x|x.count_ones().to_string()).collect();ds.sort();println!("{} {} {} {} {} {}",es.len(),add,pairs,short,pass,ds.join(","))}}
